import test from 'node:test';
import assert from 'node:assert/strict';
import {propose,rowReason,receiptText} from '../../reda-2/engine/clinic-proposals.mjs';
const base=()=>({patient:{patient_id:'fictional',patient_status:'active',plan_id:'plan',pending_count:0,open_count:0},today:'2026-09-11',cases:[],history:[]});
test('changed symptoms override ready progression and already scheduled follow-up',()=>{const d=base();d.patient.followup_status='waiting';d.decision={action:'advance',applied:false};d.cases=[{code:'changed_symptoms',status:'open'}];const p=propose(d);assert.equal(p.action,'follow_up');assert.equal(p.due,d.today);assert.doesNotMatch(p.note,/öka|aktivera/);assert.match(p.effect,/Ingen bokning/)});
test('missing feedback is not treated as missed exercise',()=>{const d=base();d.patient.missing_response=true;const p=propose(d);assert.equal(p.action,'follow_up');assert.equal(p.due,'2026-09-12');assert.match(p.why,/inte samma sak/)});
test('completed contact needs actual clinician notes and does not imply resolved cases',()=>{const d=base();d.patient.followup_status='waiting';d.cases=[{code:'requested_contact',status:'acknowledged'}];const p=propose(d);assert.equal(p.action,'complete_follow_up');assert.equal(p.note,'');assert.match(p.effect,/fortfarande bedömas/)});
test('routine applied progression is not sent back for another approval',()=>{const d=base();d.decision={action:'advance',applied:true};d.patient.decision_applied=true;assert.equal(propose(d).action,null);assert.equal(rowReason(d.patient,d.today),'Inget nytt i arbetskön')});
test('review of shadow result cannot be mistaken for activation',()=>{const d=base();d.decision={action:'advance',applied:false};const p=propose(d);assert.equal(p.action,'review_agree');assert.match(p.effect,/aktiverar ingen ny plan/)});
test('archived patients can retain unresolved cases but never get new frame proposal',()=>{const d=base();d.patient.patient_status='archived';d.prepared_frame={steps:[]};assert.equal(propose(d).action,null);d.cases=[{code:'requested_contact',status:'open'}];assert.equal(propose(d).action,'follow_up')});
test('a new ready frame is approved once, not for each ordinary step',()=>{const d=base();d.prepared_frame={steps:[{},{}]};assert.equal(propose(d).action,'approve_frame');d.frame={execution:'automatic'};d.decision={created_at:'2026-09-11',action:'advance',applied:true};assert.equal(propose(d).action,null)});
test('receipt describes actual worklist changes, never claims a message was sent',()=>{const text=receiptText({action:'follow_up',due_date:'2026-09-12',case_count:2});assert.match(text,/2 signaler kvitterade/);assert.doesNotMatch(text,/skickat|bokat|aktiverat/)});
